'use strict';
const $=id=>document.getElementById(id), modes={talk:'口播视频剪辑',footage:'素材解说成片',generate:'AI 视频生成',hybrid:'真人混搭成片'};
let token=new URLSearchParams(location.hash.slice(1)).get('session'), current=null, snapshot=null, defaultRoot='', poll=null;
history.replaceState(null,'',location.pathname);
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function message(text){$('notice').textContent=text;}
function button(text,fn){const b=el('button',text);b.onclick=async()=>{b.disabled=true;try{await fn();}catch(e){message(e.message);}finally{b.disabled=false;}};return b;}
function field(box,label,value='',type='text'){const l=el('label',label),i=el(type==='textarea'?'textarea':'input');i.id='field-'+crypto.randomUUID();l.htmlFor=i.id;if(type!=='textarea')i.type=type;if(type==='checkbox')i.checked=!!value;else i.value=value;box.append(l,i);return i;}
function card(title){const c=el('section',undefined,'card');c.append(el('h2',title));return c;}
async function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'X-Workbench-Session':token||'','Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const v=await r.json();if(!r.ok)throw Error(v.message||'操作失败');return v;}
async function upload(file){if(!file)throw Error('请先选择本地文件。');const r=await fetch('/api/upload?id='+encodeURIComponent(current),{method:'POST',headers:{'X-Workbench-Session':token||'','X-Filename':encodeURIComponent(file.name)},body:file});const value=await r.json();if(!r.ok)throw Error(value.message||'导入失败');return value;}
async function act(action,data={},background=false){const v=await api('/api/action',{id:current,action,data});message(v.job?'步骤已提交；请查看原任务进度。':'操作已保存。');if(!background&&!v.job)await updateStatus();return v;}
function clear(){if(poll)clearInterval(poll);poll=null;current=null;snapshot=null;$('body').replaceChildren();}
async function home(){clear();$('crumb').textContent='工作台 / 开始创作';const intro=card('这次想制作什么视频？');intro.append(el('p','项目保存到本机目录。页面负责方案与审看，复杂制作由 Agent 配合。'));$('body').append(intro);const grid=el('div',undefined,'grid');for(const [mode,title] of Object.entries(modes)){const c=card(title);c.append(el('p',({talk:'已有真人口播：字幕、剪切、变速和包装。',footage:'文案配真实素材：旁白、分镜、素材来源与成片。',generate:'脚本生成画面或数字人：逐任务报价和预算授权。',hybrid:'保留真人表达，插入资料片段或复杂同屏动画。'})[mode]),button('创建项目',()=>createForm(mode)));grid.append(c);}$('body').append(grid);}
function createForm(mode){clear();const c=card('创建'+modes[mode]);const title=field(c,'项目标题','新视频项目'),parent=field(c,'工程保存目录（绝对路径）',defaultRoot);c.append(el('p','在该目录下创建独立项目文件夹。源码更新不会覆盖素材和工程。'),button('创建并进入',async()=>{const p=await api('/api/create',{mode,title:title.value,parent:parent.value});await openProject(p.id);}));$('body').append(c);}
async function projects(){clear();$('crumb').textContent='工作台 / 我的项目';const data=await api('/api/projects');for(const p of data.projects){const c=card(p.title);c.append(el('p',modes[p.mode]+' · '+p.root),el('p',p.error||'项目版本 '+p.revision));if(!p.error)c.append(button('继续制作',()=>openProject(p.id)));$('body').append(c);}if(!data.projects.length)$('body').append(el('p','暂无项目，请先创建或登记旧工程。'));}
function register(){clear();const c=card('登记已有工程');const path=field(c,'原工程目录（含 .talking-edit、.director 或 .footage）');c.append(el('p','只登记本机索引，不移动或改写旧工程。无法识别的工程继续用原工具打开。'),button('登记并打开',async()=>{const p=await api('/api/register',{root:path.value});await openProject(p.id);}));$('body').append(c);}
async function updateStatus(){if(!current)return;snapshot=await api('/api/project?id='+encodeURIComponent(current));if($('status'))$('status').textContent=snapshot.status+' · 项目版本 '+snapshot.state.project.revision;if($('jobs')){$('jobs').replaceChildren();for(const j of snapshot.jobs){const line=el('p',j.action+' · '+j.status);if(j.result?.message)line.append(el('span','：'+j.result.message));$('jobs').append(line);}}}
async function openTool(review){const v=await api('/api/tool',{id:current,review});let frame=$('editor');if(!frame){frame=el('iframe');frame.id='editor';frame.title='当前项目编辑与审看';$('editor-box').append(frame);}frame.src=v.url+'#session='+encodeURIComponent(token||'');}
async function openProject(id){clear();current=id;await updateStatus();const mode=snapshot.entry.mode;$('crumb').textContent='工作台 / '+modes[mode]+' / '+snapshot.state.project.title;
const c=card('制作进度');const status=el('strong');status.id='status';c.append(status,el('p','当前工程：'+snapshot.entry.root));
c.append(button('刷新进度',updateStatus),button('检查依赖',async()=>{const d=await act('doctor');$('details').textContent=JSON.stringify(d,null,2);}),button('恢复原项目（不重提任务）',async()=>{await act('recover');message('已恢复并核查原状态；未知云任务只查询原单。');}),button('解除暂停',async()=>{await act('recover',{resume:true});}));
const details=el('pre');details.id='details';c.append(details);$('body').append(c);
const retryId=field(c,'明确失败的本地任务 ID（从原任务详情获取）');c.append(button('查看原任务详情',async()=>{await updateStatus();details.textContent=JSON.stringify(snapshot.state.tasks||snapshot.state.renders||[],null,2);}),button('允许该本地任务重试（不自动执行）',()=>act('retry-local',{task:retryId.value})));
const guide=card('与 Agent 继续协作');const instruction=`读取此仓库 SKILL.md 和 ${mode==='generate'?'92k-video-director':mode==='footage'?'narration-footage':'talking-edit'} 子Skill。当前工作台工程：${snapshot.entry.root}，项目ID：${id}。先查询原状态，使用 workbench.py api 的统一入口准备方案/打开审阅；不要替用户确认成片或预算，不重提未知云任务。`;
guide.append(el('p',instruction),button('复制接续指令',()=>navigator.clipboard.writeText(instruction)));$('body').append(guide);
if(mode==='footage')await footageEditor();else{
const tools=card('制作步骤与审阅');
if(mode!=='generate')tools.append(button('核对后采用当前风格版本',()=>act('adopt-style')));
const steps=mode==='generate'?['prepare','render']:['analyze','transcribe','roughcut','packaging','auto-gold','render'];
const names={prepare:'准备分镜任务与上限',analyze:'生成剪切候选',transcribe:'按当前配置转写',roughcut:'生成粗剪 Agent 任务',packaging:'生成包装 Agent 任务','auto-gold':'制作暗金模板（本地技术审阅）',render:'导出当前方案'};
for(const action of steps)tools.append(button(names[action],()=>act(action,{},true)));
tools.append(el('p','暗金按钮代表采用已有模板自动制作与技术检查；不会登记为你已实际听看。其他复杂包装由 Agent 制作。'));
const stages=mode==='generate'?['storyboard','budget','assets','final']:['workflow','roughcut','packaging','keyframes','final'];
const labels={workflow:'流程',roughcut:'粗剪',packaging:'包装',keyframes:'关键帧',storyboard:'分镜',budget:'预算',assets:'素材',final:'成片'};
for(const stage of stages)tools.append(button('审阅'+labels[stage],async()=>{const r=await act('review',{stage});await openTool(r.id);}));
if(mode==='generate'){const op=field(tools,'原任务 operation ID（由任务清单或 Agent 提供）');for(const action of ['quote','submit','poll','download'])tools.append(button(({quote:'查询报价',submit:'提交已授权任务',poll:'查询原单',download:'下载已付款成品'})[action],()=>act(action,{operation:op.value},true)));}
if(mode==='hybrid')hybridPanel(tools);
$('body').append(tools);const box=el('div');box.id='editor-box';$('body').append(box);await openTool();}
const jobs=card('步骤记录');const list=el('div');list.id='jobs';jobs.append(list);$('body').append(jobs);await updateStatus();poll=setInterval(()=>updateStatus().catch(e=>message(e.message)),3000);}
function hybridPanel(box){const c=card('添加／替换资料片段');const file=field(c,'已裁好的本地资料视频绝对路径'),sid=field(c,'替换时填写原片段 ID（留空新增）'),start=field(c,'真人视频入点（秒）',0,'number'),end=field(c,'真人视频出点（秒）',3,'number'),source=field(c,'资料原页面或本地原创来源'),reason=field(c,'画面与台词的匹配说明'),rights=field(c,'已核对使用许可',false,'checkbox');c.append(button('登记资料并映射（仍需审阅包装和关键帧）',()=>act('attach-source',{file:file.value,scene_id:sid.value||undefined,start:Number(start.value),end:Number(end.value),source_page:source.value,match_reason:reason.value,usage_confirmed:rights.checked,revision:snapshot.state.project.revision},true)));box.append(c);}
async function footageEditor(){
let state=structuredClone(snapshot.state.project),revision=state.revision;const c=card('文案、旁白与分镜素材');const title=field(c,'标题',state.title),script=field(c,'完整解说文案',state.script,'textarea'),audio=field(c,'选择本地旁白音频','','file'),source=field(c,'选择本地素材（视频或图片）','','file');audio.accept='audio/*';source.accept='video/*,image/*';
c.append(button('导入旁白',async()=>{const v=await upload(audio.files[0]);state.narration=v.file;state.narration_hash=v.sha256;message('旁白已导入；请保存方案。');}),button('导入素材并新增镜头',async()=>{const v=await upload(source.files[0]);state.shots.push({asset:v.file,sha256:v.sha256,duration:v.duration||3,source_in:0,line:'',source_page:'',publisher:'',product:'',match_reason:'',usage_confirmed:false,visually_reviewed:false});drawShots();message('素材已导入；填写来源与匹配说明后保存。');}));
const shots=el('div');c.append(shots);
function drawShots(){shots.replaceChildren();state.shots.forEach((s,index)=>{const pane=card('镜头 '+(index+1));const url='/media?id='+encodeURIComponent(current)+'&file='+encodeURIComponent(s.asset);const player=el(/\.(png|jpe?g|webp)$/i.test(s.asset)?'img':'video');player.src=url;player.controls=true;pane.append(player);for(const [key,label,type] of [['duration','时间轴时长（秒）','number'],['source_in','素材入点（秒）','number'],['line','本镜字幕','text'],['source_page','来源原页面／本地原创声明','text'],['publisher','发布者／作者','text'],['product','产品与版本／素材主题','text'],['match_reason','匹配台词的理由','text'],['usage_confirmed','已核对使用许可','checkbox'],['visually_reviewed','已实际审看该画面','checkbox']]){const i=field(pane,label,s[key]??'',type);i.onchange=()=>s[key]=type==='checkbox'?i.checked:type==='number'?Number(i.value):i.value;}pane.append(button('移除此镜',()=>{state.shots.splice(index,1);drawShots();}));shots.append(pane);});}drawShots();
c.append(button('保存方案',async()=>{state.title=title.value;state.script=script.value;const result=await act('update',{patch:{title:state.title,script:state.script,narration:state.narration,narration_hash:state.narration_hash,shots:state.shots},revision});revision=result.revision;state=result;message('方案已保存。之前的审阅仅适用于旧版本。');}),button('核验素材和旁白时长',async()=>{const result=await act('audit');$('details').textContent=JSON.stringify(result,null,2);}),button('审阅当前素材方案',()=>footageReview('assets')),button('合成成片',()=>act('render',{},true)),button('审阅当前成片',()=>footageReview('final')),button('刷新交付结果',showOutputs));
c.append(el('p','素材合成目前固定横版 1280×720。来源与许可由你或 Agent 核对；技术核验不能代替判断。镜头总时长须与旁白一致。'));$('body').append(c);await showOutputs();}
async function footageReview(stage){const r=await act('review',{stage});const c=card(stage==='assets'?'确认素材方案':'成片认可');c.append(el('p','仅确认刚才保存的版本。修改意见请回到方案或交给 Agent。'));for(const action of ['confirm','revise','pause'])c.append(button(({confirm:'确认',revise:'需要修改',pause:'暂停后续'})[action],async()=>{await act('decide',{request_id:r.id,revision:r.revision,action});c.remove();}));$('body').append(c);}
async function showOutputs(){await updateStatus();let c=$('outputs');if(c)c.remove();c=card('实际交付与历史输出');c.id='outputs';for(const o of snapshot.outputs){const v=el('video');v.controls=true;v.src='/media?id='+encodeURIComponent(current)+'&file='+encodeURIComponent(o.file);const a=el('a','下载字幕');a.href='/media?id='+encodeURIComponent(current)+'&file='+encodeURIComponent(o.subtitles);a.download='captions.srt';c.append(el('p','版本 '+o.revision+' · 技术导出完成，用户认可另行记录'),v,a);}$('body').append(c);}
$('home').onclick=()=>home().catch(e=>message(e.message));$('projects').onclick=()=>projects().catch(e=>message(e.message));$('register').onclick=register;
(async()=>{if(token)await api('/api/bootstrap',{});const d=await api('/api/projects');defaultRoot=d.default_root;$('version').textContent=d.version+' · 本机制作';await home();})().catch(e=>message(e.message));
